## Proper Secrets Management Solutions

### Solution 1: AWS Secrets Manager (Recommended for AWS environments)

```javascript
// secrets.js - AWS Secrets Manager implementation
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

const cache = new Map();
const CACHE_TTL = 300000; // 5 minutes

async function getSecret(secretName) {
  // Return cached value if still valid
  const cached = cache.get(secretName);
  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
    return cached.value;
  }

  try {
    const response = await client.send(new GetSecretValueCommand({
      SecretId: secretName
    }));

    const secretValue = response.SecretString;
    const parsed = JSON.parse(secretValue);

    // Cache the result
    cache.set(secretName, {
      value: parsed,
      timestamp: Date.now()
    });

    return parsed;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw new Error('Configuration error');
  }
}

// Usage in app.js
async function loadConfig() {
  const dbSecrets = await getSecret('prod/myapp/database');
  const apiSecrets = await getSecret('prod/myapp/api-keys');

  return {
    database: {
      host: dbSecrets.host,
      user: dbSecrets.username,
      password: dbSecrets.password
    },
