async function initializeApp() {
  // Load all secrets once at startup
  const secrets = await secretsManager.getSecret('prod/app/config');

  const app = require('./server')(secrets);

  app.listen(process.env.PORT || 3000, () => {
    console.log('Server running with secure secrets');
  });
}

