### 2. **Implement Secrets Manager Integration**

#### Option A: AWS Secrets Manager (Recommended for AWS deployments)

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretClient = new SecretsManagerClient({ region: process.env.AWS_REGION });

let cache = {};
let cacheExpiry = null;
const CACHE_TTL = 300000; // 5 minutes

const getSecret = async (secretName) => {
  // In-memory cache to reduce API calls
  if (cache[secretName] && cacheExpiry > Date.now()) {
    return cache[secretName];
  }

  try {
    const response = await secretClient.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );
    const secret = JSON.parse(response.SecretString);

    cache[secretName] = secret;
    cacheExpiry = Date.now() + CACHE_TTL;

    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw new Error('Failed to load configuration');
  }
};

// Initialize secrets before starting server
const loadSecrets = async () => {
  const secrets = await getSecret(process.env.SECRETS_MANAGER_NAME || 'my-app/secrets');

  // Set as environment variables for compatibility
  process.env.DATABASE_URL = secrets.databaseUrl;
  process.env.ANTHROPIC_API_KEY = secrets.anthropicApiKey;
  process.env.STRIPE_SECRET_KEY = secrets.stripeSecretKey;
  // ... etc
};

module.exports = { loadSecrets, getSecret };
```

```javascript
// app.js - Secure version
const express = require('express');
const { loadSecrets } = require('./config/secrets');

const app = express();

// Load from secrets manager before defining routes
const initialize = async () => {
  if (process.env.NODE_ENV === 'production') {
    await loadSecrets();
  } else {
    // Development: use dotenv, but validate presence
    require('dotenv').config();
    validateRequiredSecrets();
  }

  // Define routes after secrets load...
  app.get('/users', ...);
};

const validateRequiredSecrets = () => {
  const required = ['DATABASE_URL', 'ANTHROPIC_API_KEY'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
};

initialize().then(() => {
  app.listen(3000, () => {
    console.log('Server running with secure configuration');
  });
});
```

---

#### Option B: HashiCorp Vault

```javascript
// config/vault.js
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR,
});

const loadSecretsFromVault = async () => {
  // Authenticate with Vault
  const { auth } = await vault.approleLogin({
    role_id: process.env.VAULT_ROLE_ID,
    secret_id: process.env.VAULT_SECRET_ID,
  });

  vault.token = auth.client_token;

  // Read secrets
  const { data } = await vault.read('secret/my-app');

  // Set environment variables
  Object.entries(data.data).forEach(([key, value]) => {
    process.env[key.toUpperCase()] = value;
  });
};
```

---

#### Option C: Docker Secrets / Kubernetes (Container environments)

```javascript
// config/docker-secrets.js
const fs = require('fs');
const path = require('path');

const DOCKER_SECRETS_PATH = '/run/secrets';

const loadDockerSecrets = () => {
  if (!fs.existsSync(DOCKER_SECRETS_PATH)) {
    console.log('Not running in Docker, skipping secret files');
    return;
  }

  const secrets = fs.readdirSync(DOCKER_SECRETS_PATH);

  secrets.forEach(secret => {
    const secretPath = path.join(DOCKER_SECRETS_PATH, secret);
    const value = fs.readFileSync(secretPath, 'utf8').trim();
    process.env[secret.toUpperCase()] = value;

    // Log loaded secrets (names only, not values)
    console.log(`Loaded secret: ${secret}`);
  });
};
```

---

### 3. **Secure Environment Handling Pattern**

```javascript
// config/environment.js
const Joi = require('joi');

const schema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().default(3000),

  // Secrets reference for production
  SECRETS_MANAGER_NAME: Joi.string().when('NODE_ENV', {
    is: 'production',
    then: Joi.required()
  }),

  // Direct values only allowed in non-production
  DATABASE_URL: Joi.string().uri().when('NODE_ENV', {
    is: 'production',
    then: Joi.forbidden(), // Enforce secrets manager in prod
    otherwise: Joi.required()
  }),
  ANTHROPIC_API_KEY: Joi.string().when('NODE_ENV', {
    is: 'production',
    then: Joi.forbidden(),
    otherwise: Joi.required()
  }),
  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk-test-/).when('NODE_ENV', {
    is: 'production',
    then: Joi.forbidden(),
    otherwise: Joi.optional()
  }),
}).unknown(true);

const validateEnv = () => {
  const { error, value } = schema.validate(process.env);

  if (error) {
    throw new Error(`Environment validation failed: ${error.message}`);
  }

  // Mask secrets in any logging
  const masked = { ...value };
  if (value.STRIPE_SECRET_KEY) {
    masked.STRIPE_SECRET_KEY = '***REDACTED***';
  }
  // ... mask other secrets

  console.log('Environment configured:', masked);

  return value;
};

module.exports = { validateEnv };
```

