// SECURE VERSION OF APP.JS
// Incorporates security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const winston = require('winston');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    }
}));

// 2. Disable fingerprinting
app.disable('x-powered-by');

// 3. Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    message: { error: 'Too many requests, please try again later.' },
    standardHeaders: true,
    legacyHeaders: false,
});
app.use(limiter);

// 4. CORS configuration
const whitelist = process.env.CORS_WHITELIST?.split(',') || ['http://localhost:3000'];
const corsOptions = {
    origin: function (origin, callback) {
        if (whitelist.indexOf(origin) !== -1 || !origin) {
            callback(null, true);
        } else {
            callback(new Error('Not allowed by CORS'));
        }
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400
};
app.use(cors(corsOptions));

// 5. Body parser with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb', parameterLimit: 10 }));

// ===== LOGGING SETUP =====

const sensitiveFields = ['password', 'token', 'secret', 'key', 'authorization', 'cookie'];
const redactFormat = winston.format((info) => {
    const redacted = { ...info };
    const redact = (obj) => {
        for (let key in obj) {
            if (sensitiveFields.some(field => key.toLowerCase().includes(field))) {
                obj[key] = '[REDACTED]';
            } else if (typeof obj[key] === 'object' && obj[key] !== null) {
                redact(obj[key]);
            }
        }
    };
    redact(redacted);
    return redacted;
});

const logger = winston.createLogger({
    level: process.env.LOG_LEVEL || 'info',
    format: winston.format.combine(
        redactFormat(),
        winston.format.timestamp(),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console(),
        new winston.transports.File({ filename: 'app.log' })
    ]
});

// ===== VALIDATION MIDDLEWARE =====

const validate = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
    }
    next();
};

// ===== ROUTES =====

app.get('/health', (req, res) => {
    logger.info('Health check accessed', { ip: req.ip });
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
    });
});

app.get('/users', (req, res) => {
    logger.info('Users list accessed', { ip: req.ip });
    res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
});

// Example of POST route with validation
app.post('/users',
    [
        body('name').isLength({ min: 1, max: 100 }).trim().escape(),
        body('email').isEmail().normalizeEmail(),
        validate
    ],
    (req, res) => {
        logger.info('User creation attempted', { 
            ip: req.ip,
            email: req.body.email 
        });
        const { name, email } = req.body;
        // In real app: save to database
        res.status(201).json({ id: Date.now(), name, email });
    }
);

// ===== ERROR HANDLING =====

// 404 handler
app.use((req, res) => {
    logger.warn('404 Not Found', { path: req.path, method: req.method, ip: req.ip });
    res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
    logger.error('Unhandled error', {
        error: err.message,
        stack: err.stack,
        path: req.path,
        method: req.method,
        ip: req.ip
    });

    const message = process.env.NODE_ENV === 'production' 
        ? 'Internal Server Error' 
        : err.message;

    res.status(err.status || 500).json({ error: message });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
    logger.info(`Server started on port ${PORT}`, { env: process.env.NODE_ENV });
});

// Set server timeout
server.timeout = 30000; // 30 seconds

// Graceful shutdown
process.on('SIGTERM', () => {
    logger.info('SIGTERM received, shutting down gracefully');
    server.close(() => {
        logger.info('Process terminated');
        process.exit(0);
    });
});

module.exports = app;

