// SECURE CONFIGURATION MODULE
// Enforces secrets management best practices

const fs = require('fs');
const path = require('path');

// ===== CONFIGURATION =====

// Allowlist of safe, non-sensitive environment variables
const SAFE_ENV_VARS = [
    'NODE_ENV',
    'PORT',
    'HOST',
    'LOG_LEVEL',
    'VAULT_ADDR',
    'VAULT_ROLE_ID',
    'AWS_REGION',
];

// Blocklist - these should NEVER be in environment variables
const SENSITIVE_PATTERNS = [
    /PASSWORD/i,
    /SECRET/i,
    /TOKEN/i,
    /KEY/i,
    /API_KEY/i,
    /PRIVATE_KEY/i,
    /CREDENTIAL/i,
];

// ===== VALIDATION FUNCTIONS =====

/**
 * Check if .env files exist in the repository
 * They should be gitignored and never committed
 */
function checkForEnvFiles() {
    const dangerousFiles = ['.env', '.env.local', '.env.production', '.env.test'];
    const found = dangerousFiles.filter(file => {
        try {
            fs.accessSync(path.join(process.cwd(), file));
            return true;
        } catch {
            return false;
        }
    });

    if (found.length > 0) {
        console.warn('⚠️  WARNING: .env files found in repository:');
        found.forEach(f => console.warn(`   - ${f}`));
        console.warn('   These should be added to .gitignore and never committed!');
    }
    return found;
}

/**
 * Verify no secrets are in environment variables
 */
function checkForSecretsInEnv() {
    const violations = [];

    for (const [key, value] of Object.entries(process.env)) {
        for (const pattern of SENSITIVE_PATTERNS) {
            if (pattern.test(key) && !SAFE_ENV_VARS.includes(key)) {
                violations.push(key);
                break;
            }
        }
    }

    if (violations.length > 0) {
        console.error('❌ SECURITY ERROR: Secrets detected in environment variables:');
        violations.forEach(v => console.error(`   - ${v}`));
        console.error('   Secrets must be loaded from a secrets manager, not environment variables!');
        return false;
    }

    return true;
}

/**
 * Validate required configuration
 */
function validateConfig() {
    const required = ['NODE_ENV', 'PORT'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
        console.error(`❌ Missing required config: ${missing.join(', ')}`);
        return false;
    }

    return true;
}

// ===== SECRETS MANAGER INTERFACE =====

/**
 * Abstract secrets manager interface
 * Implement this with your preferred secrets manager (AWS, Vault, Azure, etc.)
 */
class SecretsManager {
    constructor() {
        if (this.constructor === SecretsManager) {
            throw new Error('Cannot instantiate abstract class');
        }
    }

    async getSecret(name) {
        throw new Error('Must implement getSecret()');
    }
}

/**
 * Example: AWS Secrets Manager implementation
 */
class AWSSecretsManager extends SecretsManager {
    constructor(region) {
        super();
        const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');
        this.client = new SecretsManagerClient({ region });
        this.GetSecretValueCommand = require('@aws-sdk/client-secrets-manager').GetSecretValueCommand;
    }

    async getSecret(name) {
        const response = await this.client.send(
            new this.GetSecretValueCommand({ SecretId: name })
        );
        return JSON.parse(response.SecretString);
    }
}

/**
 * Example: Development-only in-memory secrets (DO NOT USE IN PRODUCTION)
 */
class DevelopmentSecretsManager extends SecretsManager {
    constructor() {
        super();
        console.warn('⚠️  Using development secrets manager - NOT FOR PRODUCTION');
        // In dev, load from a local file that IS gitignored
        this.secrets = this.loadDevSecrets();
    }

    loadDevSecrets() {
        try {
            const devSecretsPath = path.join(process.cwd(), '.secrets.json');
            if (!fs.existsSync(devSecretsPath)) {
                console.error('❌ .secrets.json not found. Create it from .secrets.example.json');
                process.exit(1);
            }
            return JSON.parse(fs.readFileSync(devSecretsPath, 'utf8'));
        } catch (err) {
            console.error('❌ Failed to load dev secrets:', err.message);
            process.exit(1);
        }
    }

    async getSecret(name) {
        if (!this.secrets[name]) {
            throw new Error(`Secret not found: ${name}`);
        }
        return this.secrets[name];
    }
}

// ===== INITIALIZATION =====

function initializeSecurity() {
    console.log('🔒 Initializing security checks...\n');

    // Check 1: No .env files should be in repo
    checkForEnvFiles();
    console.log();

    // Check 2: No secrets in environment
    if (!checkForSecretsInEnv()) {
        process.exit(1);
    }
    console.log('✅ No secrets found in environment variables');

    // Check 3: Required config present
    if (!validateConfig()) {
        process.exit(1);
    }
    console.log('✅ Required configuration validated');

    // Check 4: Select appropriate secrets manager
    const secretsManager = process.env.NODE_ENV === 'production'
        ? new AWSSecretsManager(process.env.AWS_REGION)
        : new DevelopmentSecretsManager();

    console.log(`✅ Secrets manager initialized: ${secretsManager.constructor.name}\n`);

    return { secretsManager };
}

module.exports = {
    initializeSecurity,
    SecretsManager,
    AWSSecretsManager,
    DevelopmentSecretsManager,
    checkForEnvFiles,
    checkForSecretsInEnv,
    validateConfig,
};

