## Complete Secure Secrets Management Implementation

Here's a production-ready secrets module:

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

class SecureSecretManager {
  constructor() {
    this.secrets = new Map();
    this.checksums = new Map();
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
  }

  async load(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secrets = JSON.parse(response.SecretString);

      // Calculate checksum for integrity verification
      const checksum = crypto
        .createHash('sha256')
        .update(response.SecretString)
        .digest('hex');

      this.checksums.set(secretName, checksum);
      this.secrets.set(secretName, secrets);

      // Schedule rotation check
      this.scheduleRotationCheck(secretName);

      return secrets;
    } catch (error) {
      console.error(`Failed to load secret ${secretName}:`, error);
      throw error;
    }
  }

  get(key, secretName = 'prod/myapp') {
    const secrets = this.secrets.get(secretName);
    if (!secrets) {
      throw new Error(`Secret ${secretName} not loaded`);
    }

    const value = secrets[key];
    if (!value) {
      throw new Error(`Key ${key} not found in ${secretName}`);
    }

    return value;
  }

  // Prevent logging secrets accidentally
  toJSON() {
    return { status: '[REDACTED - contains secrets]' };
  }

  scheduleRotationCheck(secretName) {
    // Check for rotation every hour
    setInterval(async () => {
      try {
        await this.checkForRotation(secretName);
      } catch (error) {
        console.error('Rotation check failed:', error);
      }
    }, 60 * 60 * 1000);
  }

  async checkForRotation(secretName) {
    // Reload and compare checksums
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await this.client.send(command);

    const newChecksum = crypto
      .createHash('sha256')
      .update(response.SecretString)
      .digest('hex');

    if (newChecksum !== this.checksums.get(secretName)) {
      console.warn('Secret rotation detected - reloading');
      await this.load(secretName);
    }
  }
}

module.exports = new SecureSecretManager();
```

