```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function loadSecrets() {
  try {
    // Retrieve database credentials
    const dbCommand = new GetSecretValueCommand({ SecretId: 'prod/myapp/database' });
    const dbResponse = await client.send(dbCommand);
    const dbCredentials = JSON.parse(dbResponse.SecretString);

    // Retrieve API keys
    const apiKeysCommand = new GetSecretValueCommand({ SecretId: 'prod/myapp/api-keys' });
    const apiKeysResponse = await client.send(apiKeysCommand);
    global.secrets = {
      database: dbCredentials,
      apiKeys: JSON.parse(apiKeysResponse.SecretString)
    };
  } catch (err) {
    console.error('Failed to load secrets from AWS:', err);
    process.exit(1);
  }
}

// Initialize app only after secrets are loaded
