#!/usr/bin/env node
/**
 * Secure Credential Rotation Script
 * 
 * This script helps track and manage credential rotation without
 * exposing secret values in logs or output.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Configuration
const SECRETS_FILE = path.join(__dirname, '..', '.env.test');
const ROTATION_LOG = path.join(__dirname, '..', 'rotation-log.json');

/**
 * Generate a secure preview of a secret (first 4 + last 4 chars)
 * WARNING: Only use this for tracking, never for verification or display
 */
function generatePreview(secret) {
  if (!secret || secret.length < 10) {
    return '[INVALID_LENGTH]';
  }
  const first = secret.slice(0, 4);
  const last = secret.slice(-4);
  const masked = '*'.repeat(secret.length - 8);
  return `${first}${masked}${last}`;
}

/**
 * Hash a secret for comparison (does not expose value)
 */
function hashSecret(secret) {
  return crypto.createHash('sha256').update(secret).digest('hex');
}

/**
 * Read secrets file and generate rotation tracking data
 */
function generateRotationPlan() {
  try {
    const content = fs.readFileSync(SECRETS_FILE, 'utf8');
    const lines = content.split('\n').filter(line => line.trim() && !line.startsWith('#'));

    const rotationPlan = {
      generatedAt: new Date().toISOString(),
      secrets: [],
      notes: 'This plan contains HASHES and PREVIEWS only - no actual secret values'
    };

    for (const line of lines) {
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('='); // Handle values that may contain =

      if (key && value) {
        rotationPlan.secrets.push({
          variable: key.trim(),
          // Store hash for post-rotation verification
          currentHash: hashSecret(value.trim()),
          // Preview for tracking spreadsheet
          preview: generatePreview(value.trim()),
          action: 'ROTATE',
          status: 'PENDING'
        });
      }
    }

    // Save rotation plan
    fs.writeFileSync(ROTATION_LOG, JSON.stringify(rotationPlan, null, 2));

    return rotationPlan;
  } catch (error) {
    console.error('Error generating rotation plan:', error.message);
    process.exit(1);
  }
}

/**
 * Verify that secrets have been rotated by comparing hashes
 */
function verifyRotation(newSecretsFile) {
  if (!fs.existsSync(ROTATION_LOG)) {
    console.error('No rotation log found. Run with --plan first.');
    process.exit(1);
  }

