// Environment Variable Validation Module
// Ensures all required secrets are present before app starts

const REQUIRED_VARS = [
  'NODE_ENV',
  'DATABASE_URL',
  'JWT_SECRET',
  'STRIPE_SECRET_KEY',
];

const OPTIONAL_VARS = [
  'PORT',
  'ALLOWED_ORIGINS',
  'LOG_LEVEL',
];

/**
 * Validates that all required environment variables are present
 * @throws {Error} If any required variable is missing
 */
function validateEnv() {
  const missing = [];

  for (const varName of REQUIRED_VARS) {
    if (!process.env[varName]) {
      missing.push(varName);
    }
  }

  if (missing.length > 0) {
    console.error('❌ Missing required environment variables:');
    missing.forEach(v => console.error(`   - ${v}`));
    console.error('\nPlease set these variables in your environment or secrets manager.');
    console.error('DO NOT commit .env files to version control!\n');
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  // Validate DATABASE_URL format
  if (process.env.DATABASE_URL) {
    const dbUrlPattern = /^postgresql:\/\/[^:]+:[^@]+@[^:]+:\d+\/\w+$/;
    if (!dbUrlPattern.test(process.env.DATABASE_URL)) {
      console.warn('⚠️  WARNING: DATABASE_URL format may be invalid');
    }
  }

  // Validate JWT_SECRET strength
  if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    console.warn('⚠️  WARNING: JWT_SECRET should be at least 32 characters for security');
  }

  // Warn if Stripe key looks like test mode in production
  if (process.env.NODE_ENV === 'production' && 
      process.env.STRIPE_SECRET_KEY?.startsWith('sk-test-')) {
    console.warn('⚠️  WARNING: Production environment using Stripe TEST key');
  }

  console.log('✅ Environment variables validated successfully');

  // Log optional vars that are set
  for (const varName of OPTIONAL_VARS) {
    if (process.env[varName]) {
      console.log(`   - ${varName}: ${varName.includes('SECRET') ? '***' : 'set'}`);
    }
  }
}

/**
 * Securely retrieves a secret, ensuring it exists
 * @param {string} key - Environment variable name
 * @param {boolean} required - Whether the variable is required
 * @returns {string|undefined} The secret value or undefined
 */
function getSecret(key, required = true) {
  const value = process.env[key];

  if (required && !value) {
    throw new Error(`Required secret ${key} is not configured`);
  }

  return value;
}

module.exports = {
  validateEnv,
  getSecret,
  REQUIRED_VARS,
  OPTIONAL_VARS
};

// Example: Secure Secrets Management using AWS Secrets Manager
// This is the recommended approach for production applications

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes cache
  }

  /**
   * Retrieves a secret from AWS Secrets Manager
   * @param {string} secretName - Name of the secret
   * @returns {Promise<Object>} Parsed secret values
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        // Binary secret - decode from base64
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Clears the secrets cache
   */
  clearCache() {
    this.cache.clear();
  }
}

// Alternative: HashiCorp Vault implementation
class VaultSecretsManager {
  constructor() {
    this.vaultAddr = process.env.VAULT_ADDR;
    this.vaultToken = process.env.VAULT_TOKEN;
    this.cache = new Map();
  }

  async getSecret(path) {
    const response = await fetch(`${this.vaultAddr}/v1/secret/data/${path}`, {
      headers: {
        'X-Vault-Token': this.vaultToken
      }
    });

    if (!response.ok) {
      throw new Error(`Vault request failed: ${response.status}`);
    }

    const data = await response.json();
    return data.data.data;
  }
}

