### **Vulnerability 7: No Authentication/Authorization**

**Severity:** High  
**OWASP Category:** A01:2021 - Broken Access Control  
**Description:** As routes are added, there's no pattern in place for protecting sensitive endpoints.

**Current Issue:**
```javascript
// No authentication middleware
// Anyone can access all endpoints
```

**Recommendation:**
```javascript
const jwt = require('jsonwebtoken');
const { promisify } = require('util');

// Authentication middleware
const authenticate = async (req, res, next) => {
  try {
    let token;

    if (req.headers.authorization?.startsWith('Bearer')) {
      token = req.headers.authorization.split(' ')[1];
    }

    if (!token) {
      return res.status(401).json({
        status: 'fail',
        message: 'You are not logged in. Please log in to get access.'
      });
    }

    // Verify token
    const decoded = await promisify(jwt.verify)(token, process.env.JWT_SECRET);

    // Check if user still exists (optional but recommended)
    const user = await User.findById(decoded.id);
    if (!user) {
      return res.status(401).json({
        status: 'fail',
        message: 'The user belonging to this token no longer exists.'
      });
    }

    // Check if user changed password after token was issued
    if (user.changedPasswordAfter(decoded.iat)) {
      return res.status(401).json({
        status: 'fail',
        message: 'User recently changed password. Please log in again.'
      });
    }

    req.user = user;
    next();
  } catch (err) {
    res.status(401).json({
      status: 'fail',
      message: 'Invalid token'
    });
  }
};

// Authorization middleware
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        status: 'fail',
        message: 'You do not have permission to perform this action'
      });
    }
    next();
  };
};

// Usage
app.get('/admin/users', authenticate, authorize('admin'), (req, res) => {
  // Admin only endpoint
});
```

