const loadEnv = () => {
  if (process.env.NODE_ENV === 'production') {
    throw new Error('DO NOT USE .env FILES IN PRODUCTION');
  }

  const envPath = path.join(__dirname, '..', '.env');

  // Verify file permissions (should be 600)
